import{_ as a,o as t,c as o,ag as r}from"./chunks/framework.DPTJCqgd.js";const u=JSON.parse('{"title":"Get started with Harness Desktop","description":"","frontmatter":{"editSource":"docs/user/guide/index.md","editSourceUrl":"https://github.com/Bestbbb/deepseek-harness-desktop/edit/main/docs/user/guide/index.md"},"headers":[],"relativePath":"en/guide/quickstart.md","filePath":"en/guide/quickstart.md"}'),s={name:"en/guide/quickstart.md"};function n(i,e,d,l,p,c){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="get-started-with-harness-desktop" tabindex="-1">Get started with Harness Desktop <a class="header-anchor" href="#get-started-with-harness-desktop" aria-label="Permalink to &quot;Get started with Harness Desktop&quot;">​</a></h1><p>Use Harness Desktop to connect a model and run a task in a local project. This guide is for installer users: the app starts its own Harness runtime, so you do not need to start a Web server or install a separate CLI. For source development, follow the <a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/main/README.md#run-from-source" target="_blank" rel="noreferrer">build instructions</a>.</p><h2 id="install-and-open-the-app" tabindex="-1">Install and open the app <a class="header-anchor" href="#install-and-open-the-app" aria-label="Permalink to &quot;Install and open the app&quot;">​</a></h2><ol><li>Open <a href="https://github.com/Bestbbb/deepseek-harness-desktop/releases/tag/desktop-v0.1.3-alpha.1" target="_blank" rel="noreferrer">Releases</a> and choose the macOS Apple Silicon DMG or Windows x64 installer under <strong>Assets</strong>. Check that release&#39;s bundled version and platform notes; a source checkout can be newer than the available installers.</li><li>Verify the download against the release&#39;s SHA-256 checksums before installing. These community previews are ad-hoc signed and not notarized on macOS, and unsigned on Windows. If your operating system blocks the app, review the release&#39;s platform instructions before deciding whether to allow it.</li><li>Open <strong>Harness Desktop</strong> and wait for the conversation interface. Read the first-run notice before continuing to model setup.</li></ol><p>Automatic updates are not configured. Check Releases for a newer installer; the <a href="https://github.com/Bestbbb/deepseek-harness-desktop/blob/main/apps/desktop/README.md" target="_blank" rel="noreferrer">desktop guide</a> describes data isolation and distribution limits.</p><h2 id="configure-a-model" tabindex="-1">Configure a model <a class="header-anchor" href="#configure-a-model" aria-label="Permalink to &quot;Configure a model&quot;">​</a></h2><p>Open <strong>Settings → Models</strong>. Enter a <a href="https://platform.deepseek.com/" target="_blank" rel="noreferrer">DeepSeek API key</a> in the DeepSeek card, or use <strong>Add provider</strong> or <strong>Add a custom provider</strong> for another supported provider or gateway. Save the configuration, then select a model in the conversation composer.</p><p>The <a href="./providers">model configuration guide</a> covers authentication, model discovery, image support, and gateway settings. Saving a key stores it locally; it does not prove that the provider will accept a request. Model requests use your provider&#39;s service and billing, not a bundled subscription.</p><h2 id="choose-a-workspace" tabindex="-1">Choose a workspace <a class="header-anchor" href="#choose-a-workspace" aria-label="Permalink to &quot;Choose a workspace&quot;">​</a></h2><p>Click <strong>Choose workspace</strong>, add a local project directory, and select it. The conversation composer needs a selected workspace and model before you can send a task. Start with a project you are comfortable granting the agent access to.</p><h2 id="run-a-task" tabindex="-1">Run a task <a class="header-anchor" href="#run-a-task" aria-label="Permalink to &quot;Run a task&quot;">​</a></h2><p>Start a session, choose an Agent preset, and send a small task:</p><blockquote><p>Summarize this repository and identify its main packages.</p></blockquote><p>The agent can read and edit workspace files, run commands, delegate work, and maintain a plan. The Web UI asks before operations that require approval under the active permission policy.</p><p>Read the response and any tool results before asking for larger changes. If the provider rejects the request, return to <strong>Settings → Models</strong> and check the endpoint, model, and credentials using the <a href="./providers#provider-troubleshooting">troubleshooting guide</a>. A disabled composer also requires checking the workspace and model selections.</p><h2 id="continue" tabindex="-1">Continue <a class="header-anchor" href="#continue" aria-label="Permalink to &quot;Continue&quot;">​</a></h2><ul><li><a href="./providers">Configure models</a></li><li><a href="./network-proxy">Configure a network proxy</a></li><li><a href="./python-sdk">Use the Python SDK</a></li><li><a href="./../develop/basic/">Develop a plugin</a></li></ul>',17)])])}const g=a(s,[["render",n]]);export{u as __pageData,g as default};
